    let bgmPlaylists = [];

    function loadPlaylists() {
        let saved = localStorage.getItem('celestial_all_playlists');
        if (saved) {
            try {
                let parsed = JSON.parse(saved);
                if (Array.isArray(parsed) && parsed.length > 0) {
                    if (!parsed.some(p => p.category === '★ 我的收藏')) {
                        parsed.unshift({ category: '★ 我的收藏', songs: [], prompt: '', promptEnabled: false });
                    }
                    if (!parsed.some(p => p.category === '🕒 最近播放')) {
                        parsed.splice(1, 0, { category: '🕒 最近播放', songs: [], prompt: '', promptEnabled: false });
                    }
                    // 歌单提示词字段迁移 & 本地直链真实 URL 迁移
                    let localUrls = JSON.parse(localStorage.getItem('celestial_custom_urls') || '{}');
                    parsed.forEach(p => {
                        if (typeof p.prompt !== 'string') p.prompt = '';
                        if (typeof p.promptEnabled !== 'boolean') p.promptEnabled = false;
                        if (Array.isArray(p.songs)) {
                            p.songs.forEach(s => {
                                if (s.artist === '[本地直链解析]' || !s.artist) {
                                    if (localUrls[s.title]) s.artist = localUrls[s.title];
                                    else if (customUrlDb[s.title]) s.artist = customUrlDb[s.title];
                                }
                            });
                        }
                    });
                    bgmPlaylists = parsed;
            return;
        }
            } catch (e) {}
        }
        bgmPlaylists = JSON.parse(JSON.stringify(initialDefaultPlaylists));
        // 为出厂列表补提示词字段
        bgmPlaylists.forEach(p => {
            if (typeof p.prompt !== 'string') p.prompt = '';
            if (typeof p.promptEnabled !== 'boolean') p.promptEnabled = false;
        });
        savePlaylists();
    }

    function getHistoryLimit() {
        let v = parseInt(localStorage.getItem('cr_history_limit') || '10', 10);
        return (isNaN(v) || v < 1) ? 10 : v;
    }

    function recordPlayHistory(title, artist) {
        if (!title || title === '频段静默' || title === '直连锁定中...') return;
        let histPl = bgmPlaylists.find(p => p.category === '🕒 最近播放');
        if (!histPl) {
            histPl = { category: '🕒 最近播放', songs: [], prompt: '', promptEnabled: false };
            bgmPlaylists.splice(1, 0, histPl);
        }
        let normT = normalizeStr(title);
        let normA = normalizeStr(artist || '');
        let existIdx = histPl.songs.findIndex(s => normalizeStr(s.title) === normT && normalizeStr(s.artist || '') === normA);
        if (existIdx !== -1) {
            histPl.songs.splice(existIdx, 1);
        }
        histPl.songs.unshift({ title: title.trim(), artist: (artist || '').trim() });
        let limit = getHistoryLimit();
        if (histPl.songs.length > limit) {
            histPl.songs = histPl.songs.slice(0, limit);
        }
        savePlaylists();
        if (!state.collapsed) {
            renderPlaylists();
        }
    }

    function savePlaylists() {
        localStorage.setItem('celestial_all_playlists', JSON.stringify(bgmPlaylists));
    }
    loadPlaylists();

    // === AI DJ 配置默认项与读取 ===
    const DEFAULT_DJ_PROMPT = `你是一位顶级的电影/动漫影视配乐总监与动态氛围 BGM DJ。
你的唯一任务是：仔细分析当前最新的剧情走向、人物情绪、环境氛围与叙事张力，为本幕剧情挑选一首绝佳的背景音乐（BGM）。

【决策优先级与准则】：
1. 优先纯音乐、动漫无人声配乐、电影原声 OST、氛围器乐与古典爵士，避免嘈杂人声打乱阅读心流。
2. 优先在【当前电台已有曲库列表】中挑选高度契合的曲目（可实现 0 毫秒极速播放）。
3. 若已有曲库中均不符合本轮特殊意境（如克苏鲁恐怖、1920年代爵士、热血决战、温馨日常等），请从你的海量音乐知识库中挑选一首知名且高适配度的经典原声曲目。
4. 严格输出标准格式，禁止输出任何寒暄、废话或解释，只输出一行：
[点一首歌: 歌名 - 歌手]`;

    const DEFAULT_FRESH_PROMPT = `你是一位顶级的电影/动漫影视配乐总监与动态氛围 BGM DJ。
你的唯一任务是：分析最新剧情的情绪 / 氛围 / 张力，为本幕挑选一首绝佳 BGM。

【决策优先级与准则】：
1. 优先纯音乐、动漫无人声配乐、电影原声 OST、氛围器乐与古典爵士，避免嘈杂人声打乱阅读心流。
2. 【当前电台已有曲库】与【歌单提示词】仅作为“风格 / 情绪 / 器乐类型”的参考锚点，严禁直接复用其中任何一首（标题与歌手均不得重复）。你必须从你的海量音乐知识库中挑选一首与参考列表整体风格高度一致、但不在列表中的新曲，以保证新鲜感与惊喜感。
3. 若剧情为特殊意境（如克苏鲁恐怖、1920年代爵士、热血决战等），在同风格约束下优先该细分风格的经典原声。
4. 严格输出标准格式，禁止任何寒暄、解释或额外文本，只输出一行：
[点一首歌: 歌名 - 歌手]`;

    const DEFAULT_DJ_PRESETS = [
        { id: 'default-classic', name: '\uD83C\uDFAC 经典优先在库', prompt: DEFAULT_DJ_PROMPT },
        { id: 'default-fresh', name: '\u2728 新鲜感\u00B7参考风格选新曲', prompt: DEFAULT_FRESH_PROMPT }
    ];

    function getDjSettings() {
        return {
            apiUrl: localStorage.getItem('cr_dj_api_url') || 'https://api.openai.com/v1',
            apiKey: localStorage.getItem('cr_dj_api_key') || '',
            model: localStorage.getItem('cr_dj_model') || 'gpt-4o-mini',
            historyDepth: (()=>{let v=parseInt(localStorage.getItem('cr_dj_history_depth') || '0',10); return Number.isFinite(v)? v:0;})(),
            autoTrigger: localStorage.getItem('cr_dj_auto_trigger') !== 'false',
            debugMode: localStorage.getItem('cr_dj_debug_mode') === 'true',
            systemPrompt: localStorage.getItem('cr_dj_system_prompt') || DEFAULT_DJ_PROMPT,
            endInjection: localStorage.getItem('cr_dj_end_injection') || '',
            initAutoplay: localStorage.getItem('cr_init_autoplay') === 'true',
            glassEffect: localStorage.getItem('cr_glass_effect') !== 'false',
            spectrum: localStorage.getItem('cr_spectrum') === 'true'
        };
    }

    function saveDjSettings(cfg) {
        localStorage.setItem('cr_dj_api_url', cfg.apiUrl.trim());
        localStorage.setItem('cr_dj_api_key', cfg.apiKey.trim());
        localStorage.setItem('cr_dj_model', cfg.model.trim());
        localStorage.setItem('cr_dj_history_depth', cfg.historyDepth.toString());
        localStorage.setItem('cr_dj_auto_trigger', cfg.autoTrigger ? 'true' : 'false');
        localStorage.setItem('cr_dj_debug_mode', cfg.debugMode ? 'true' : 'false');
        localStorage.setItem('cr_dj_system_prompt', cfg.systemPrompt.trim());
        localStorage.setItem('cr_dj_end_injection', (cfg.endInjection || '').trim());
        localStorage.setItem('cr_init_autoplay', cfg.initAutoplay ? 'true' : 'false');
        localStorage.setItem('cr_glass_effect', cfg.glassEffect ? 'true' : 'false');
        localStorage.setItem('cr_spectrum', cfg.spectrum ? 'true' : 'false');
    }

    function applyGlassEffect(on) {
        $ctn.toggleClass('no-glass', !on);
    }

    // === DJ 角色预设（prompt-only） ===
    function loadDjPresets() {
        try {
            let raw = localStorage.getItem('cr_dj_presets');
            if (raw) {
                let arr = JSON.parse(raw);
                if (Array.isArray(arr) && arr.length > 0) return arr;
            }
        } catch (e) {}
        // 首次初始化：两条出厂预设（可编辑可删）
        let init = JSON.parse(JSON.stringify(DEFAULT_DJ_PRESETS));
        try { localStorage.setItem('cr_dj_presets', JSON.stringify(init)); } catch (e) {}
        try { localStorage.setItem('cr_dj_active_preset_id', init[0].id); } catch (e) {}
        return init;
    }
    function saveDjPresets(list) {
        localStorage.setItem('cr_dj_presets', JSON.stringify(list));
    }
    function getActivePresetId() {
        return localStorage.getItem('cr_dj_active_preset_id') || '';
    }
    function setActivePresetId(id) {
        localStorage.setItem('cr_dj_active_preset_id', id);
    }
    function getActivePreset() {
        let list = loadDjPresets();
        let aid = getActivePresetId();
        if (aid) {
            let hit = list.find(p => p.id === aid);
            if (hit) return hit;
        }
        return list[0] || null;
    }
    function ensurePresetsMigrated() {
        let list = loadDjPresets();
        // 若本地已有 cr_dj_system_prompt 且与出厂均不等，视作用户自定义，追加为一条
        try {
            let cur = localStorage.getItem('cr_dj_system_prompt');
            if (cur && cur.trim() && cur.trim() !== DEFAULT_DJ_PROMPT.trim() && cur.trim() !== DEFAULT_FRESH_PROMPT.trim()) {
                if (!list.some(p => p.prompt.trim() === cur.trim())) {
                    list.push({ id: 'migrated-' + Date.now().toString(36), name: '我的预设', prompt: cur.trim() });
                    saveDjPresets(list);
                }
            }
        } catch (e) {}
        // 保证 activeId 有效
        let aid = getActivePresetId();
        if (!aid || !list.some(p => p.id === aid)) {
            setActivePresetId(list[0].id);
        }
        return list;
    }
    function getEffectiveSystemPrompt() {
        let ap = getActivePreset();
        if (ap && typeof ap.prompt === 'string' && ap.prompt.trim()) return ap.prompt;
        try { return localStorage.getItem('cr_dj_system_prompt') || DEFAULT_DJ_PROMPT; } catch (e) { return DEFAULT_DJ_PROMPT; }
    }
    function renderPresetSelect() {
        let $sel = $('#cr-preset-select');
        if (!$sel.length) return;
        let list = loadDjPresets();
        let aid = getActivePresetId() || (list[0] && list[0].id) || '';
        let html = '';
        list.forEach(p => {
            html += `<option value="${p.id}">${p.name}</option>`;
        });
        $sel.html(html);
        $sel.val(aid);
    }

    const T_CHARS = "愛礙奧壩罷擺敗頒辦絆幫綁鎊謗剝飽寶報鮑輩貝鋇狽備憊繃筆畢斃幣閉邊編貶變辯辮標飈賓濱繽瀕餅撥鉢鉑駁卜補財參慘蠶燦倉蒼艙測策層詫攙摻蟬饞讒纏產闡顫倀長腸嘗償廠暢鈔車徹塵陳襯撐稱懲誠騁癡遲齒恥沖蟲寵疇躊醜籌齣芻處礎觸辭詞賜聰蔥從叢湊竄錯達帶貸擔單鄲撣膽導燈鄧敵滌遞締點墊電澱釣調諜疊頂訂釘東動棟凍鬥犢獨讀賭鍍鍛斷緞兌隊對噸頓鈍奪鵝額惡餓兒爾餌貳發罰閥煩繁飯範販飛廢費紛墳奮憤糞豐風楓瘋鋒鳳膚膚輻撫輔賦複負婦蓋幹趕岡鋼剛崗綱閣個給鞏貢溝構購夠轂顧掛關觀館慣貫廣廣獷規歸龜櫃貴國過漢號賀橫轟紅宏轟後護壺滬華畫劃話懷壞歡環還緩換喚瘓煥渙黃謊揮輝彙會匯繪毀機雞跡積績擊激及級濟計記際繼紀夾莢頰賈鉀價駕監堅箋間艱揀檢鹼減薦鑒鍵將獎槳講醬驕膠澆矯腳攪繳絞較階節傑結潔緊錦僅進燼盡驚莖睛經頸靜鏡徑痙競凈糾舊駒舉劇據巨懼捲絕覺決鈞軍駿開凱鄶鄺擴闊臘蠟蘭攔欄藍籃覽懶纜爛濫撈勞樂類淚釐離裡鯉禮麗厲勵壢歷曆煉練戀殮鏈涼糧兩輛諒療遼繚獵臨鄰鱗凜賃齡貫";
    const S_CHARS = "爱碍奥坝败颁办绊帮帮绑镑谤剥饱宝报鲍辈贝钡狈备惫绷笔毕毙币闭边编贬变辩辫标飙宾滨缤濒饼拨钵铂驳卜补财参惨蚕灿仓苍舱测策层诧搀掺蝉馋谗缠产阐颤伥长肠尝偿厂畅钞车彻尘陈衬撑称惩诚骋痴迟齿耻冲虫宠畴踌丑筹出刍处础触辞词赐聪葱从丛凑窜错达带贷担单郸掸胆导灯邓敌涤缔缔点垫电淀钓调谍叠顶订钉东动栋冻斗犊独读赌镀锻断缎兑队对吨顿钝夺鹅额恶饿儿尔饵贰发罚阀烦繁饭范贩飞废费纷坟奋愤粪丰风枫疯锋凤肤肤辐抚辅复负妇盖干赶岗钢刚岗纲阁个给巩贡沟构购够毂顾挂关观馆惯贯广广犷规归龟柜贵国过汉号贺横轰红宏轰后护壶沪华画划话怀坏欢环还缓换唤痪焕涣黄谎挥辉汇会汇绘毁机鸡迹积绩击激及级济计记际继纪夹荚颊贾钾价驾监坚笺间艰拣检碱减荐鉴键将奖桨讲酱骄胶浇矫脚搅缴绞较阶节杰结洁紧锦仅进烬尽惊茎睛经颈静径痉竞净纠旧驹举剧据巨惧卷绝觉决钧军骏开凯侩邝扩阔腊蜡兰拦栏蓝篮览懒缆烂滥捞劳乐类泪厘离里鲤礼丽厉励沥历历炼练恋殓链凉粮两辆谅辽缭猎临邻鳞凛赁龄贯";

    function normalizeStr(str) {
        if (!str) return '';
        let res = '';
        for (let i = 0; i < str.length; i++) {
            const char = str[i];
            const idx = T_CHARS.indexOf(char);
            res += (idx !== -1) ? S_CHARS[idx] : char;
        }

        const diacritics = {
            'ä': 'a', 'ö': 'o', 'ü': 'u', 'ß': 'ss',
            'é': 'e', 'è': 'e', 'ê': 'e', 'ë': 'e',
            'á': 'a', 'à': 'a', 'â': 'a', 'å': 'a', 'ά': 'a',
            'í': 'i', 'ì': 'i', 'î': 'i', 'ï': 'i', 'ɪ': 'i',
            'ó': 'o', 'ò': 'o', 'ô': 'o', 'ø': 'o',
            'ú': 'u', 'ù': 'u', 'û': 'u',
            'ə': 'a', 'æ': 'ae', '0': 'o', '1': 'i',
            '機': '机', '動': '动'
        };
        res = res.toLowerCase();
        for (let k in diacritics) {
            res = res.replaceAll(k, diacritics[k]);
        }
        return res.replace(/[\s\-_,.'’"“”（\(\)\[\]【】《》/:\!！？\?~★·]/g, '');
    }

    function cleanEditionTags(title) {
        if (!title) return '';
        return title.replace(/[\(\[\{（【](?:remaster(?:ed)?|mono|stereo|deluxe|version|edition|original\s*recording|19\d\d\s*recording|\d{4}\s*remaster).*?[\)\]\}）】]/gi, '').trim();
    }

    function cleanTrackQuery(rawTitle, rawArtist) {
        let title = (rawTitle || '').trim();
        let artist = (rawArtist || '').trim();

        title = title.replace(/^[\s《"“'‘【\[（(]+|[\s》"”'’】\]）)]+$/g, '').trim();
        artist = artist.replace(/^[\s《"“'‘【\[（(]+|[\s》"”'’】\]）)]+$/g, '').trim();

        let fullRawTitle = artist ? `${title} - ${artist}` : title;

        let isOstIntent = false;
        const ostRegex = /[\(\（\[【](?:tv|anime|ost|bgm|soundtrack|theme|插曲|主题曲|片头曲|片尾曲|原声|动画|角色歌).*?[\)\）\]】]/gi;
        if (ostRegex.test(title) || ostRegex.test(artist) || ostRegex.test(fullRawTitle)) {
            isOstIntent = true;
        }
        title = title.replace(ostRegex, '').trim();
        artist = artist.replace(ostRegex, '').trim();
        let fullTitle = fullRawTitle.replace(ostRegex, '').trim();

        let subTitle = '';
        let matchSub = title.match(/^(.+?)\s*[\(（](.+?)[\)）]$/);
        if (matchSub) {
            title = matchSub[1].trim();
            subTitle = matchSub[2].trim();
        }

        let aliasTitle = title.toLowerCase()
            .replaceAll('ə', 'a').replaceAll('ά', 'a').replaceAll('ɪ', 'i').replaceAll('0', 'o').replaceAll('ä', 'a')
            .replaceAll('立body!机st', '立body機motion').replaceAll('立body机st', '立body機motion');

        let aliasFullTitle = fullTitle.toLowerCase()
            .replaceAll('ə', 'a').replaceAll('ά', 'a').replaceAll('ɪ', 'i').replaceAll('0', 'o').replaceAll('ä', 'a')
            .replaceAll('立body!机st', '立body機motion').replaceAll('立body机st', '立body機motion');

        return { title, artist, fullTitle, aliasTitle, aliasFullTitle, subTitle, isOstIntent };
    }

