        .song-item.playing::before { content: '►'; opacity: 1; color: #C4A77D; animation: crBlink 1s infinite alternate;}
        .song-item.playing .song-name { color: #C4A77D; font-weight: bold; }
        .song-item.playing .song-artist { color: rgba(196,167,125,0.6); }

        .custom-playlist-actions { padding: 6px; display: flex; gap: 6px; background: rgba(0,0,0,0.4); border-top: 1px solid rgba(255,255,255,0.05); flex-shrink: 0;}
        .cp-input { flex: 1; padding: 4px 6px; font-size: 10px; transition: border-color 0.3s;}
        .cp-input:focus { border-color: #C4A77D !important; }
        .cp-btn { background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.15); color: #ccc; padding: 3px 6px; font-size: 10px; cursor: pointer; border-radius: 2px; transition: 0.2s; white-space: nowrap;}
        .cp-btn:hover { background: rgba(255,255,255,0.15); color: #fff; border-color: rgba(255,255,255,0.3); }

        /* 底部播放控制面板与同色系精美音量条 */
        .bgm-player-controls { padding: 10px 15px 10px; background: linear-gradient(0deg, rgba(6,8,12,0.95), rgba(12,16,24,0.95)); border-top: 1px solid rgba(196,167,125,0.25); display: flex; flex-direction: column; gap: 6px; position: relative; z-index: 2; flex-shrink: 0;}

        .bgm-info-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
        .bgm-now-title-box { flex: 1; overflow: hidden; display: flex; flex-direction: column; align-items: center; justify-content: center; }
        .bgm-now-playing { font-size: 12px; color: #C4A77D; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: bold; letter-spacing: 1px; width: 100%;}
        .bgm-now-artist { font-size: 9px; color: rgba(196,167,125,0.6); text-align: center; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; width: 100%;}

        /* 暗金同色系矢量播放器工具按钮（收藏 & 下载） */
        .cr-player-tool-btn {
            cursor: pointer; width: 26px; height: 26px; border-radius: 50%;
            background: rgba(196,167,125,0.06); border: 1px solid rgba(196,167,125,0.3);
            display: inline-flex; align-items: center; justify-content: center;
            transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1); flex-shrink: 0; color: #C4A77D;
        }
        .cr-player-tool-btn:hover {
            background: rgba(196,167,125,0.2); border-color: #C4A77D;
            box-shadow: 0 0 10px rgba(196,167,125,0.35); transform: scale(1.1);
        }
        .cr-player-tool-btn.is-fav {
            background: rgba(196,167,125,0.18); border-color: #C4A77D;
            box-shadow: 0 0 8px rgba(196,167,125,0.4);
        }
        .cr-player-tool-btn svg { display: block; }

        .bgm-ctrl-row { display: flex; justify-content: center; gap: 20px; align-items: center; margin-top: 2px;}
        .bgm-ctrl-btn { background: none; border: none; font-size: 16px; cursor: pointer; transition: 0.2s; padding: 0; outline: none; display: flex; align-items: center; justify-content: center;}
        .bgm-ctrl-btn:hover { transform: scale(1.1); }

        .bgm-play-btn { width: 34px; height: 34px; border-radius: 50%; border: 1px solid rgba(196,167,125,0.3); background: rgba(196,167,125,0.05); position: relative;}
        .bgm-play-btn:hover { background: rgba(196,167,125,0.2); border-color: #C4A77D; box-shadow: 0 0 15px rgba(196,167,125,0.4); transform: scale(1.05);}
        .play-icon { width: 0; height: 0; border-style: solid; border-width: 6px 0 6px 10px; border-color: transparent transparent transparent #C4A77D; margin-left: 3px; pointer-events: none; transition: border-color 0.2s;}
        .pause-icon { width: 10px; height: 12px; border-left: 3px solid #C4A77D; border-right: 3px solid #C4A77D; box-sizing: border-box; pointer-events: none; transition: border-color 0.2s;}
        .bgm-play-btn:hover .play-icon { border-color: transparent transparent transparent #fff; }
        .bgm-play-btn:hover .pause-icon { border-color: #fff; }

        .ctrl-icon-prev, .ctrl-icon-next { position: relative; width: 16px; height: 12px; pointer-events: none; display: flex; align-items: center; }

        .ctrl-icon-next::before { content: ''; position: absolute; left: 0; width: 0; height: 0; border-style: solid; border-width: 5px 0 5px 7px; border-color: transparent transparent transparent rgba(196,167,125,0.7); transition: 0.2s;}
        .ctrl-icon-next::after { content: ''; position: absolute; left: 7px; width: 0; height: 0; border-style: solid; border-width: 5px 0 5px 7px; border-color: transparent transparent transparent rgba(196,167,125,0.7); transition: 0.2s;}
        .ctrl-icon-next span { position: absolute; right: 0; width: 2px; height: 10px; background: rgba(196,167,125,0.7); transition: 0.2s;}

        .ctrl-icon-prev::before { content: ''; position: absolute; right: 0; width: 0; height: 0; border-style: solid; border-width: 5px 7px 5px 0; border-color: transparent rgba(196,167,125,0.7) transparent transparent; transition: 0.2s;}
        .ctrl-icon-prev::after { content: ''; position: absolute; right: 7px; width: 0; height: 0; border-style: solid; border-width: 5px 7px 5px 0; border-color: transparent rgba(196,167,125,0.7) transparent transparent; transition: 0.2s;}
        .ctrl-icon-prev span { position: absolute; left: 0; width: 2px; height: 10px; background: rgba(196,167,125,0.7); transition: 0.2s;}

        .bgm-ctrl-btn:hover .ctrl-icon-next::before, .bgm-ctrl-btn:hover .ctrl-icon-next::after { border-color: transparent transparent transparent #fff; }
        .bgm-ctrl-btn:hover .ctrl-icon-next span { background: #fff; }
        .bgm-ctrl-btn:hover .ctrl-icon-prev::before, .bgm-ctrl-btn:hover .ctrl-icon-prev::after { border-color: transparent #fff transparent transparent; }
        .bgm-ctrl-btn:hover .ctrl-icon-prev span { background: #fff; }

        .bgm-progress { width: 100%; height: 3px; background: rgba(255,255,255,0.1); border-radius: 1.5px; cursor: pointer; position: relative; overflow: hidden;}
        .bgm-progress-fill { height: 100%; background: #C4A77D; border-radius: 1.5px; width: 0%; box-shadow: 0 0 5px #C4A77D; pointer-events: none; transition: width 0.1s linear;}

        /* 赛博等离子频谱波形音量律动条样式 */
        .bgm-volume-row { display: flex; align-items: center; gap: 8px; padding: 2px 4px; }
        .cr-vol-icon {
            display: inline-flex; align-items: center; justify-content: center;
            cursor: pointer; user-select: none; transition: transform 0.2s, opacity 0.2s;
            width: 16px; height: 16px; flex-shrink: 0;
        }
        .cr-vol-icon:hover { transform: scale(1.15); opacity: 1; }
        .cr-vol-icon svg { display: block; }

        .cr-vol-visualizer-container {
            flex: 1; height: 18px; position: relative; display: flex; align-items: center;
        }
        .cr-vol-visualizer {
            position: absolute; left: 0; top: 0; width: 100%; height: 100%;
            display: flex; align-items: center; gap: 2.5px;
            pointer-events: none; user-select: none;
        }
        .cr-vol-bar {
            flex: 1; height: 3px; min-height: 2px;
            background: rgba(255,255,255,0.08); border-radius: 1px;
            transition: height 0.08s ease, background 0.15s, box-shadow 0.15s;
            pointer-events: none;
        }
        .cr-vol-bar.active {
            background: linear-gradient(0deg, #C4A77D, #FFF5DF);
            box-shadow: 0 0 5px rgba(196,167,125,0.5);
        }
        /* 律动改由合成器 scaleY 动画驱动：仅播放态激活，振幅随 --cr-vol 缩放，0.1875 即 3px 底部保底 */
        .cr-vol-visualizer.playing .cr-vol-bar.active {
            height: 16px;
            animation: crVolDanceA 0.62s ease-in-out infinite;
        }
        /* 奇偶柱采用不同波形，配合创建时逐柱轮换的时长与相位，形成长短峰交错、永不循环的频谱观感 */
        .cr-vol-visualizer.playing .cr-vol-bar.active:nth-child(even) {
            animation-name: crVolDanceB;
        }
        @keyframes crVolDanceA {
            0%, 100% { transform: scaleY(0.1875); }
            50% { transform: scaleY(max(0.1875, calc(1.3 * var(--cr-vol, 1)))); }
        }
        @keyframes crVolDanceB {
            0%, 100% { transform: scaleY(0.1875); }
            30% { transform: scaleY(max(0.1875, calc(0.95 * var(--cr-vol, 1)))); }
            50% { transform: scaleY(max(0.1875, calc(0.45 * var(--cr-vol, 1)))); }
            72% { transform: scaleY(max(0.1875, calc(1.1 * var(--cr-vol, 1)))); }
        }
        /* 真实频谱模式：由 JS 逐帧写 transform（合成器属性，不触发布局），关闭 CSS 波形 */
        .cr-vol-visualizer.playing.real-spectrum .cr-vol-bar.active {
            animation: none; height: 16px;
        }

        .cr-vol-native-slider {
            position: absolute; left: 0; top: 0; width: 100%; height: 100%;
            margin: 0; padding: 0; opacity: 0; cursor: pointer; z-index: 2;
            -webkit-appearance: none; appearance: none; background: transparent; border: none;
        }

        .cr-vol-text {
            font-size: 10px; color: #C4A77D; opacity: 0.85; width: 30px; text-align: right;
            font-family: 'Jura', monospace; user-select: none; flex-shrink: 0; letter-spacing: 0.5px;
        }

        /* 播放器转圈加载指示器 */
        .cr-play-spinner {
            width: 14px; height: 14px;
            border: 2px solid rgba(196, 167, 125, 0.25);
            border-top-color: #C4A77D;
            border-radius: 50%;
            animation: crSpin 0.75s linear infinite;
            pointer-events: none;
            display: inline-block;
        }
        @keyframes crSpin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        /* 歌单列表项加载态 */
        .song-item.loading {
            background: linear-gradient(90deg, rgba(196,167,125,0.06), transparent);
        }
        .song-item.loading::before {
            content: '◌'; opacity: 1; color: #C4A77D;
            animation: crBlink 0.8s infinite alternate;
        }
        .song-item.loading .song-name { color: #C4A77D; }

        /* 贴边把手加载呼吸态 */
        .cr-edge-dot.loading {
            background: #C4A77D; box-shadow: 0 0 6px #C4A77D; animation: crPulseDot 1s infinite ease-in-out;
        }

        /* 现代化浮动非阻塞 Toast (零布局挤压) */
        .cr-player-toast {
            position: absolute; bottom: 8px; left: 50%;
            transform: translateX(-50%) translateY(10px);
            background: rgba(12, 16, 23, 0.95);
            border: 1px solid rgba(196, 167, 125, 0.4);
            border-radius: 14px;
            color: #C4A77D;
            font-size: 10px;
            padding: 4px 12px;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.75);
            opacity: 0;
            pointer-events: none;
            transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
            z-index: 100020;
            white-space: nowrap;
            letter-spacing: 0.5px;
        }
        .cr-player-toast.show {
            transform: translateX(-50%) translateY(0);
            opacity: 1;
        }

        /* 模态框通用遮罩层与外框 */
        .cr-modal-overlay {
            position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(4, 6, 10, 0.92); backdrop-filter: blur(10px);
            z-index: 100010; display: none; flex-direction: column;
            box-sizing: border-box; justify-content: center;
        }
        .cr-modal-box {
            background: #0d1117; border: 1px solid rgba(196,167,125,0.4);
            border-radius: 8px; padding: 14px; display: flex; flex-direction: column; gap: 9px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.85); max-height: 90%; overflow-y: auto; margin: 14px;
        }
        .cr-modal-title {
            font-size: 11px; color: #C4A77D; font-weight: bold; text-align: center;
