        .cr-modal-list::-webkit-scrollbar-thumb { background: rgba(196,167,125,0.3); }

        .cr-modal-item {
            padding: 8px 10px; font-size: 11px; color: #d0d0d0; cursor: pointer; border-radius: 4px;
            background: rgba(196,167,125,0.06); border: 1px solid rgba(196,167,125,0.2); transition: 0.2s;
            white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
            flex-shrink: 0; min-height: 32px; height: 32px; box-sizing: border-box;
