            box-shadow: 0 0 8px rgba(196,167,125,0.35); transform: translateX(2px);
        }

        /* === 现代化工业级 AI DJ 设置面板专属样式 === */
        #cr-settings-modal {
            padding: 0; justify-content: stretch; overflow: hidden; background: rgba(8, 10, 14, 0.97);
        }
        .cr-settings-container {
            display: flex; flex-direction: column; width: 100%; height: 100%; overflow: hidden;
        }
        .cr-settings-header {
            padding: 10px 12px; display: flex; justify-content: space-between; align-items: center;
            border-bottom: 1px solid rgba(255,255,255,0.06);
            background: linear-gradient(90deg, rgba(196,167,125,0.12) 0%, transparent 100%);
            flex-shrink: 0;
        }
