        .cr-settings-body::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }
        .cr-settings-body::-webkit-scrollbar-thumb { background: rgba(196,167,125,0.3); border-radius: 2px; }

        .cr-tab-pane { display: none; flex-direction: column; gap: 8px; }
        .cr-tab-pane.active { display: flex; }

        /* 卡片容器 */
        .cr-card {
            background: rgba(255,255,255,0.025); border: 1px solid rgba(255,255,255,0.06);
