        }

        .cr-cfg-row { display: flex; flex-direction: column; gap: 3px; }
        .cr-cfg-label { font-size: 10px; color: #aaa; display: flex; justify-content: space-between; align-items: center;}
        .cr-cfg-link { font-size: 9px; color: #C4A77D; cursor: pointer; text-decoration: underline; opacity: 0.85; transition: 0.2s;}
        .cr-cfg-link:hover { opacity: 1; color: #fff; }

        .cr-input-wrap { position: relative; display: flex; align-items: center; }
        .cr-cfg-input { width: 100%; padding: 5px 7px; font-size: 10px; }
        .cr-cfg-textarea { width: 100%; height: 130px; padding: 6px 8px; font-size: 9.5px; resize: vertical; line-height: 1.4; font-family: 'Fira Code', monospace;}
        .cr-input-btn {
            position: absolute; right: 4px; background: rgba(255,255,255,0.06);
            border: 1px solid rgba(255,255,255,0.12); border-radius: 3px; color: #ccc;
            font-size: 9px; padding: 2px 5px; cursor: pointer; transition: 0.2s;
        }
        .cr-input-btn:hover { background: rgba(196,167,125,0.25); color: #fff; border-color: #C4A77D; }

        /* 模型快捷 Chips */
