        .cr-preset-btn.del-btn:hover { background: rgba(248,113,113,0.15); color: #f87171; border-color: #f87171; }

        /* 歌单提示词管理区 */
        .cr-pl-toolbar {
            display: flex; justify-content: space-between; align-items: center; padding: 6px 8px;
            background: rgba(255,255,255,0.025); border: 1px solid rgba(255,255,255,0.06); border-radius: 4px;
        }
        .cr-pl-filter-input {
            width: 100%; background: #111 !important; border: 1px solid rgba(255,255,255,0.1) !important;
