    // === 智能贴边位置计算与应用 ===
    function applyDockPosition(isDraggingNow = false, dragX = null, dragY = null) {
        let winWidth = window.innerWidth || document.documentElement.clientWidth || 400;
        let winHeight = window.innerHeight || document.documentElement.clientHeight || 800;

        if (state.collapsed) {
            $ctn.removeClass('is-panel').addClass('is-collapsed');
            if (dockSide === 'left') {
                $ctn.removeClass('dock-right').addClass('dock-left');
                $('#cr-edge-arrow').text('›');
                $ctn[0].style.setProperty('left', isDraggingNow && dragX !== null ? Math.max(0, dragX) + 'px' : '0px', 'important');
                $ctn[0].style.setProperty('right', 'auto', 'important');
            } else {
                $ctn.removeClass('dock-left').addClass('dock-right');
                $('#cr-edge-arrow').text('‹');
                $ctn[0].style.setProperty('right', isDraggingNow && dragX !== null ? Math.max(0, winWidth - dragX - 24) + 'px' : '0px', 'important');
                $ctn[0].style.setProperty('left', 'auto', 'important');
            }
            let curY = (isDraggingNow && dragY !== null) ? dragY : dockTop;
            curY = Math.max(10, Math.min(curY, winHeight - 64));
            $ctn[0].style.setProperty('top', curY + 'px', 'important');
            $ctn[0].style.setProperty('bottom', 'auto', 'important');
        } else {
            $ctn.removeClass('is-collapsed dock-left dock-right').addClass('is-panel');
            let panelTop = Math.max(10, Math.min(dockTop, winHeight - 540));
            $ctn[0].style.setProperty('top', panelTop + 'px', 'important');
            $ctn[0].style.setProperty('bottom', 'auto', 'important');
            if (dockSide === 'left') {
                $ctn[0].style.setProperty('left', '10px', 'important');
                $ctn[0].style.setProperty('right', 'auto', 'important');
            } else {
                $ctn[0].style.setProperty('right', '10px', 'important');
                $ctn[0].style.setProperty('left', 'auto', 'important');
            }
        }
    }
    applyDockPosition();

    let isDragging = false;
    let dragStartX, dragStartY;
    let initialLeft, initialTop;

    $ctn.on('mousedown touchstart', '.celestial-drag-handle, #celestial-radio-container.is-collapsed', function(e) {
        if ($(e.target).closest('.cr-cat-drag-handle, .cr-cat-order-btn, .cr-del-pl, .cr-del-song, .song-action-btn, .cr-player-tool-btn, .cr-header-btn, input, button, select, textarea').length > 0) return;

        isDragging = false;
        const evt = e.type === 'touchstart' ? e.originalEvent.touches[0] : e;
        dragStartX = evt.clientX;
        dragStartY = evt.clientY;

        const rect = $ctn[0].getBoundingClientRect();
        initialLeft = rect.left;
        initialTop = rect.top;

        overlay.show();
        if (e.type === 'mousedown') e.preventDefault();
    });

    overlay.on('mousemove touchmove', function(e) {
        const moveEvt = e.type === 'touchmove' ? e.originalEvent.touches[0] : e;
        const deltaX = moveEvt.clientX - dragStartX;
        const deltaY = moveEvt.clientY - dragStartY;

        if (Math.abs(deltaX) > 8 || Math.abs(deltaY) > 8) {
            isDragging = true;
            let curX = initialLeft + deltaX;
            let curY = initialTop + deltaY;

            let winWidth = window.innerWidth || 400;
            dockSide = (curX + 15 < winWidth / 2) ? 'left' : 'right';
            applyDockPosition(true, curX, curY);
        }
        if (e.type === 'touchmove') e.preventDefault();
    });

    overlay.on('mouseup touchend', function(e) {
        overlay.hide();

        if (isDragging) {
            const rect = $ctn[0].getBoundingClientRect();
            let winWidth = window.innerWidth || 400;
            let winHeight = window.innerHeight || 800;

            dockSide = (rect.left + rect.width / 2 < winWidth / 2) ? 'left' : 'right';
            dockTop = Math.max(10, Math.min(rect.top, winHeight - 64));

            localStorage.setItem('cr_dock_side', dockSide);
            localStorage.setItem('cr_dock_top', dockTop.toString());

            applyDockPosition();
            setTimeout(() => { isDragging = false; }, 80);
        } else {
            if (state.collapsed) {
                state.collapsed = false;
                applyDockPosition();
                renderPlaylists();
            }
        }
    });

