            let ep = url.replace(/\/+$/, '') + '/chat/completions';
            let res = await fetch(ep, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    ...(key ? { 'Authorization': 'Bearer ' + key } : {})
                },
                body: JSON.stringify({
                    model: model,
                    messages: [{ role: 'user', content: 'hi' }],
                    max_tokens: 2
                })
            });
            if (res.ok || res.status === 400 || res.status === 200) {
                alert('✅ API 接口连通测试响应成功！(状态码: ' + res.status + ')');
            } else {
                alert('⚠️ 接口响应状态码: ' + res.status + ' (' + res.statusText + ')，请检查地址与密钥。');
