    // 移植自 RpgCombat 三段式：原生 SillyTavern 破窗 > await getChatMessages > 补 getCurrentMessage
    async function extractStoryContext(depth = 0) {
        const _awaitIfPromise = async (v) => (v && typeof v.then === 'function' ? await v : v);
        const _pick = (m) => (m.raw_content ?? m.content ?? m.message ?? m.mes ?? '').trim();
        const _isAI = (m) => m.role === 'assistant' || m.is_user === false;
        try {
            let allMsgs = null;
            // 1. 首选：原生破窗法（参考《酒馆询问机》与 RpgCombat:11478）
            let tavernWin = window;
            try {
                while (tavernWin && tavernWin !== tavernWin.parent) {
                    let p = tavernWin.parent;
                    try { if (p && p.SillyTavern) { tavernWin = p; break; } } catch (e2) {}
                    if (p === tavernWin) break;
                    tavernWin = p;
        }
            } catch (e) {}
            if (tavernWin && tavernWin.SillyTavern && typeof tavernWin.SillyTavern.getContext === 'function') {
                try {
                    const ctx = tavernWin.SillyTavern.getContext();
                    if (ctx && Array.isArray(ctx.chat)) {
                        allMsgs = JSON.parse(JSON.stringify(ctx.chat));
                    }
        } catch (e) {}
            }
            if (!allMsgs || allMsgs.length === 0) {
                try {
                    let pw = window.parent;
                    if (pw && pw.SillyTavern && typeof pw.SillyTavern.getContext === 'function') {
                        const ctx2 = pw.SillyTavern.getContext();
                        if (ctx2 && Array.isArray(ctx2.chat)) allMsgs = JSON.parse(JSON.stringify(ctx2.chat));
                    }
        } catch (e) {}
            }
            // 2. 备选：酒馆助手接口兜底（RpgCombat:11502 - hide_state:'all' + await）
            if ((!allMsgs || allMsgs.length === 0) && typeof getChatMessages === 'function') {
                try {
                    let curId = '{{lastMessageId}}';
                    if (typeof getCurrentMessageId === 'function') {
                        const tmp = getCurrentMessageId();
                        if (tmp !== undefined && tmp !== null) curId = tmp;
                    } else if (tavernWin && typeof tavernWin.getCurrentMessageId === 'function') {
                        try { curId = tavernWin.getCurrentMessageId(); } catch (e) {}
                    }
                    let raw = getChatMessages('0-' + curId, { hide_state: 'all' });
                    raw = await _awaitIfPromise(raw);
                    if (Array.isArray(raw) && raw.length > 0) allMsgs = raw;
                    else if (Array.isArray(raw)) allMsgs = raw;
        } catch (e) {}
            }
            if ((!allMsgs || allMsgs.length === 0) && typeof window.parent.getChatMessages === 'function') {
                try {
                    let raw2 = window.parent.getChatMessages('all');
                    raw2 = await _awaitIfPromise(raw2);
                    if (Array.isArray(raw2)) allMsgs = raw2;
        } catch (e) {}
            }
            if ((!allMsgs || allMsgs.length === 0) && typeof getChatMessages === 'function') {
                try {
                    let raw3 = getChatMessages('all');
                    raw3 = await _awaitIfPromise(raw3);
                    if (Array.isArray(raw3) && raw3.length > 0) allMsgs = raw3;
        } catch (e) {}
            }
            // 3. 补正在生成楼（RpgCombat:11508 - ctx.chat 未落库时）
            if (typeof getCurrentMessage === 'function' && typeof getCurrentMessageId === 'function') {
                try {
                    const curId2 = getCurrentMessageId();
                    if (curId2 !== '{{lastMessageId}}' && curId2 !== null && curId2 !== undefined) {
                        const curMsg = getCurrentMessage();
                        const actual = Array.isArray(curMsg) && curMsg.length > 0 ? curMsg[0] : curMsg;
                        const curNum = Number(curId2);
                        const exists = Array.isArray(allMsgs) && allMsgs.some(m => Number(m.message_id ?? m.id) === curNum || Number(m.swipe_id) === curNum);
                        if (actual && !exists) {
                            if (!Array.isArray(allMsgs)) allMsgs = [];
                            allMsgs.push({
                                message_id: curNum, id: curNum,
                                name: actual.name || 'AI', role: 'assistant', is_user: false,
                                mes: actual.message || actual.mes || actual.content || actual.raw_content || '',
                                message: actual.message || actual.mes || actual.content || actual.raw_content || '',
                                raw_content: actual.raw_content || actual.content || actual.message || actual.mes || ''
                            });
                        }
                    }
        } catch (e) {}
            }
            if (allMsgs && allMsgs.length > 0) {
                if (depth === 0) {
                    for (let i = allMsgs.length - 1; i >= 0; i--) {
                        let m = allMsgs[i];
                        if (!_isAI(m)) continue;
                        let c = _pick(m);
                        if (c) return `[AI 当前最新剧情]:\n${c}`;
                    }
                    for (let i = allMsgs.length - 1; i >= 0; i--) {
                        let m = allMsgs[i];
                        if (!_isAI(m)) continue;
                        let s = m.swipes?.[m.swipe_id];
                        if (s && s.trim()) return `[AI 当前最新剧情]:\n${s.trim()}`;
                    }
        } else {
                    let d = Number(depth);
                    if (!Number.isFinite(d) || d < 0) d = 0;
                    let count = Math.max(1, d * 2);
                    let sliced = allMsgs.slice(-count);
                    let result = [];
                    sliced.forEach(m => {
                        let c = _pick(m);
                        if (!c) {
                            let s = m.swipes?.[m.swipe_id];
                            if (s && s.trim()) c = s.trim();
                        }
                        if (!c) return;
                        let speaker = _isAI(m) ? (m.name || 'AI') : (m.name || 'User');
                        result.push(`[${speaker}]:\n${c}`);
                    });
                    if (result.length > 0) return result.join('\n\n');
        }
            }
            // DOM 备用兜底（兼容 iframe：document + window.parent.document）
            let domBlocks = null;
            try { domBlocks = document.querySelectorAll('.mes_text'); } catch (e) {}
            if ((!domBlocks || domBlocks.length === 0) && window.parent && window.parent.document) {
                try { domBlocks = window.parent.document.querySelectorAll('.mes_text'); } catch (e) {}
            }
            if ((!domBlocks || domBlocks.length === 0) && tavernWin && tavernWin.document) {
                try { domBlocks = tavernWin.document.querySelectorAll('.mes_text'); } catch (e) {}
            }
            if (domBlocks && domBlocks.length > 0) {
                if (depth === 0) {
                    for (let i = domBlocks.length - 1; i >= 0; i--) {
                        let el = domBlocks[i];
                        let txt = (el.innerText || el.textContent || '').trim();
                        if (!txt) continue;
                        let mesEl = el.closest ? el.closest('.mes') : null;
                        if (mesEl) {
                            let isUser = mesEl.classList.contains('user_mes') || mesEl.getAttribute('is_user') === 'true';
                            if (isUser) continue;
                        }
                        return `[AI 当前最新剧情]:\n${txt}`;
                    }
                    let last = domBlocks[domBlocks.length - 1];
                    let t = (last.innerText || last.textContent || '').trim();
                    if (t) return `[AI 当前最新剧情]:\n${t}`;
        } else {
                    let d2 = Number(depth);
                    if (!Number.isFinite(d2) || d2 < 0) d2 = 0;
                    let count = Math.max(1, d2 * 2);
                    let slicedDom = Array.from(domBlocks).slice(-count);
                    let parts = slicedDom.map((el, i) => {
                        let t = (el.innerText || el.textContent || '').trim();
                        return t ? `[剧情片段 ${i+1}]:\n${t}` : null;
                    }).filter(Boolean);
                    if (parts.length > 0) return parts.join('\n\n');
        }
            }
        } catch (e) {}
        return "[AI 当前最新剧情]:\n(未捕获到剧情正文，请结合常驻氛围选曲)";
    }

    // 生成曲库摘要供 AI 参考
    function getLibrarySummaryForPrompt(opts) {
        let filterEnabled = opts && opts.filterEnabled;
        let summary = [];
        bgmPlaylists.forEach(pl => {
            if (pl.songs.length === 0) return;
            if (filterEnabled && !pl.promptEnabled) return;
            let songListStr = pl.songs.slice(0, 8).map(s => s.artist ? `${s.title} - ${s.artist}` : s.title).join(', ');
            summary.push(`- 【${pl.category}】: ${songListStr}`);
        });
        return summary.join('\n');
    }

    function getPlaylistPromptBlocks() {
        let blocks = [];
        bgmPlaylists.forEach(pl => {
            if (!pl.promptEnabled) return;
            let txt = (pl.prompt || '').trim();
            if (!txt) return;
            blocks.push(`- 【${pl.category}】提示词：${txt}`);
        });
        return blocks.join('\n');
    }

    function renderSettingsPlaylistPrompts(filterText = '') {
        let $list = $('#cr-pl-prompt-list');
        if (!$list.length) return;
        if (bgmPlaylists.length === 0) {
            $list.html('<div style="font-size:10px;color:#666;text-align:center;padding:12px;">暂无频段</div>');
            return;
        }
        let kw = (filterText || '').trim().toLowerCase();
        let html = '';
        let matchCount = 0;
        bgmPlaylists.forEach((pl, idx) => {
            if (kw && !pl.category.toLowerCase().includes(kw) && !pl.songs.some(s => (s.title + ' ' + (s.artist || '')).toLowerCase().includes(kw))) {
                return;
            }
            matchCount++;
            let checked = pl.promptEnabled ? 'checked' : '';
            let isEnabledClass = pl.promptEnabled ? 'is-enabled' : '';
            let chipsHtml = pl.songs.slice(0, 8).map(s => {
                let label = s.artist ? `${s.title} - ${s.artist}` : s.title;
                let safeLabel = label.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
                return `<span class="cr-pl-song-chip" title="${safeLabel}">${safeLabel}</span>`;
            }).join('');
            if (!chipsHtml) chipsHtml = '<span class="cr-pl-song-chip" style="color:#666;">(空频段)</span>';

            let safePrompt = (pl.prompt || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
            let safeCategory = pl.category.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

            html += `<div class="cr-pl-prompt-item ${isEnabledClass}" data-idx="${idx}">`
                + `<div class="cr-pl-prompt-top-row">`
                + `<label class="cr-pl-prompt-title-label" for="cr-pl-check-${idx}">`
                + `<input type="checkbox" id="cr-pl-check-${idx}" class="cr-pl-prompt-enabled" data-idx="${idx}" ${checked}>`
                + `<span class="cr-pl-cat-name">${safeCategory}</span>`
                + `<span class="cr-pl-cat-count">${pl.songs.length}首</span>`
                + `</label>`
                + `<span class="cr-pl-status-tag">${pl.promptEnabled ? '● 随Sidecar发送' : '○ 未启用'}</span>`
                + `</div>`
                + `<div class="cr-pl-chips-wrap">${chipsHtml}</div>`
                + `<textarea class="cr-pl-prompt-input" data-idx="${idx}" placeholder="为【${safeCategory}】填写意境提示词（如：空灵雨境、神秘器乐...）">${safePrompt}</textarea>`
                + `</div>`;
        });
        if (matchCount === 0) {
            $list.html('<div style="font-size:10px;color:#666;text-align:center;padding:12px;">未找到匹配频段</div>');
        } else {
            $list.html(html);
        }
    }

    // === 核心：Sidecar 专职 AI DJ 异步决策引擎 ===
    async function triggerAiDjDecision(isManual = false) {
        const cfg = getDjSettings();

        if (!cfg.apiKey) {
            if (isManual) {
                alert("指挥官，请先在右上角 ⚙ 设置中配置您的 AI 接口地址与 API Key！");
                openSettingsModal();
            }
            return;
        }

        $('#cr-manual-dj-btn').addClass('loading').text('🤖 选曲中...');
        showPlayerToast('🤖 AI DJ 正在研判当前剧情氛围...', 3000);

        const storyContext = await extractStoryContext(cfg.historyDepth);
        const librarySummary = getLibrarySummaryForPrompt({ filterEnabled: true });
        const playlistPromptBlocks = getPlaylistPromptBlocks();
        // 空正文阻断：避免随机选歌
        if (!storyContext || storyContext.includes('(未捕获到剧情正文') || storyContext.trim().endsWith(':\\n')) {
            const msg = '未捕获到0层正文，已阻断选歌。请确认聊天存在AI回复或稍后重试。';
            if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning(msg);
            else if (typeof alert === 'function') alert(msg);
            console.warn('[太空电台] storyContext 为空，已阻断:', storyContext);
            $('#cr-manual-dj-btn').removeClass('loading').text('✨ AI选歌');
            showPlayerToast('⚠️ 未捕获到正文', 2500);
            return;
        }
        if (cfg.debugMode) console.debug('[太空电台·0层调试] storyContext 长度:', storyContext.length, '前300字:', storyContext.slice(0,300));

        let _payloadParts = [];
        if (librarySummary) _payloadParts.push(`【当前电台已有本地频段与精选曲目】：\n${librarySummary}`);
        if (playlistPromptBlocks) _payloadParts.push(`【歌单提示词（玩家勾选）】：\n${playlistPromptBlocks}`);
        _payloadParts.push(`【剧情正文内容 (参考深度: ${cfg.historyDepth} 层)】：\n${storyContext}`);
        _payloadParts.push(`请基于上述故事意境，挑选最合适的一首背景音乐（BGM），严格输出格式为：[点一首歌: 歌名 - 歌手]`);
        if (cfg.endInjection && cfg.endInjection.trim()) {
            _payloadParts.push(cfg.endInjection.trim());
        }
        const userPayload = _payloadParts.join('\n\n');

        let endpoint = cfg.apiUrl.replace(/\/+$/, '');
        if (!endpoint.endsWith('/chat/completions')) {
            endpoint = `${endpoint}/chat/completions`;
        }

        const requestBody = {
            model: cfg.model,
            messages: [
                { role: "system", content: getEffectiveSystemPrompt() },
                { role: "user", content: userPayload }
            ],
            temperature: 0.65
        };

        if (cfg.debugMode && playlistPromptBlocks) {
            console.log('%c📚 歌单提示词（已勾选）:', 'color: #a78bfa;', playlistPromptBlocks);
        }
        if (cfg.debugMode && cfg.endInjection && cfg.endInjection.trim()) {
            console.log('%c📌 用户末尾注入要求 (End Injection):', 'color: #f59e0b; font-weight: bold;', cfg.endInjection.trim());
        }
        if (cfg.debugMode) {
            console.groupCollapsed('%c🎧 [太空电台·AI DJ 选歌决策探测]', 'color: #C4A77D; font-weight: bold; font-size: 12px;');
            console.log('%c📡 目标接口 (Endpoint):', 'color: #888;', endpoint);
            console.log('%c🤖 请求模型 (Model):', 'color: #888;', cfg.model);
            console.log('%c📏 上下文深度 (Depth):', 'color: #888;', `${cfg.historyDepth} 层`);
            console.log('%c📜 系统提示词 (System Prompt):', 'color: #4ade80;', getEffectiveSystemPrompt());
            console.log('%c💬 上下文 Payload (User Message):', 'color: #60a5fa;', userPayload);
        }

        try {
            const resp = await fetch(endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${cfg.apiKey}`
        },
                body: JSON.stringify(requestBody)
            });

            if (!resp.ok) {
                let errText = await resp.text();
                throw new Error(`HTTP ${resp.status}: ${errText}`);
            }

            const data = await resp.json();
            let aiResponse = "";
            if (data.choices && data.choices[0] && data.choices[0].message) {
                aiResponse = data.choices[0].message.content || "";
            }

            if (cfg.debugMode) {
                console.log('%c⚡ 原始模型返回 (Raw AI Response):', 'color: #f59e0b;', aiResponse);
            }

            // 解析决策结果 [点一首歌: 歌名 - 歌手]
            const regex = /\[\s*点一首歌\s*[:：]\s*([^\]]+?)\s*\]/i;
            let match = regex.exec(aiResponse);
            let finalCommand = match ? match[1].trim() : aiResponse.trim().replace(/^[`"'\s]+|[`"'\s]+$/g, '');

            if (cfg.debugMode) {
                console.log('%c🎵 提取目标曲目:', 'color: #C4A77D; font-weight: bold;', finalCommand);
                console.groupEnd();
            }

            if (finalCommand) {
                let songTitle = finalCommand;
                let songArtist = "";
                let splitIdx = finalCommand.lastIndexOf('-');
                if (splitIdx !== -1) {
                    songTitle = finalCommand.substring(0, splitIdx).trim();
                    songArtist = finalCommand.substring(splitIdx + 1).trim();
        }

                showPlayerToast(`✨ AI DJ 精选: ${finalCommand}`, 3000);

                playDirect(songTitle, songArtist);
            }
        } catch (err) {
            console.error('[太空电台·AI DJ] 请求失败:', err);
            if (cfg.debugMode) {
                console.error('%c❌ AI DJ 请求发生异常:', 'color: #ef4444;', err);
                console.groupEnd();
            }
            showPlayerToast(`⚠️ AI选歌连接受阻: ${err.message || '网络异常'}`, 3500);

        } finally {
            $('#cr-manual-dj-btn').removeClass('loading').text('✨ AI选歌');
        }
    }

    $('#cr-manual-dj-btn').on('click', function(e) {
        e.stopPropagation();
        triggerAiDjDecision(true);
    });

    // === 收藏状态检查与同步 ===
    function isSongFavorited(title, artist) {
        let favPl = bgmPlaylists.find(p => p.category === '★ 我的收藏');
        if (!favPl) return false;
        let t = normalizeStr(title);
        return favPl.songs.some(s => normalizeStr(s.title) === t);
    }

    function toggleFavorite(title, artist) {
        let favPl = bgmPlaylists.find(p => p.category === '★ 我的收藏');
        if (!favPl) {
            favPl = { category: '★ 我的收藏', songs: [] };
            bgmPlaylists.unshift(favPl);
        }
        let t = normalizeStr(title);
        let sIdx = favPl.songs.findIndex(s => normalizeStr(s.title) === t);

        if (sIdx !== -1) {
            favPl.songs.splice(sIdx, 1);
            showPlayerToast(`已从我的收藏移除: ${title}`, 2000);
        } else {
            favPl.songs.unshift({ title, artist: artist || 'Unknown' });
            showPlayerToast(`★ 已收藏至我的收藏: ${title}`, 2000);
        }


        savePlaylists();
        renderPlaylists();
        updatePlayerFavBtn();
    }

    function updatePlayerFavBtn() {
        if (currentPlayingTrackInfo.title && isSongFavorited(currentPlayingTrackInfo.title, currentPlayingTrackInfo.artist)) {
            $('#cr-player-fav-btn').addClass('is-fav').html(ICONS.favSolid).attr('title', '已收藏 (点击取消收藏)');
        } else {
            $('#cr-player-fav-btn').removeClass('is-fav').html(ICONS.favOutline).attr('title', '收藏当前曲目至“我的收藏”');
        }
    }

    $('#cr-player-fav-btn').on('click', function() {
        if (!currentPlayingTrackInfo.title) return;
        toggleFavorite(currentPlayingTrackInfo.title, currentPlayingTrackInfo.artist);
    });

    // === 音频导出/下载功能 ===
    async function downloadCurrentAudio() {
        if (!audioObj.src) {
            showPlayerToast('当前无正在播放的音频', 2000);

            return;
        }

        let title = currentPlayingTrackInfo.title || $('#bgm-now-playing').text() || 'space_radio_audio';
        let artist = currentPlayingTrackInfo.artist || $('#bgm-now-artist').text() || '';
        let filename = artist && artist !== '---' ? `${title} - ${artist}.mp3` : `${title}.mp3`;
        filename = filename.replace(/[/\\?%*:|"<>]/g, '_');

        showPlayerToast('正在捕获音频流并下载...', 2500);

        try {
            const res = await fetch(audioObj.src);
            const blob = await res.blob();
            const blobUrl = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = blobUrl;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            a.remove();
            URL.revokeObjectURL(blobUrl);
            showPlayerToast('✅ 音频下载成功！', 2500);

        } catch (e) {
            const a = document.createElement('a');
            a.href = audioObj.src;
            a.target = '_blank';
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            a.remove();
            showPlayerToast('已在新标签页建立音频下载管道', 2500);

        }
    }
    $('#cr-player-dl-btn').on('click', downloadCurrentAudio);

    // === 等离子频谱波形音量控制与律动引擎 ===
    const VOL_BAR_COUNT = 24;
    const $volVis = $('#cr-vol-visualizer');
    $volVis.empty();
    // 各柱时长在互不成倍数的档位间轮换（奇偶柱波形亦不同），长短峰交错更贴近真实频谱
    const VOL_DURATIONS = [0.54, 0.71, 0.62, 0.83, 0.59, 0.76];
    for (let i = 0; i < VOL_BAR_COUNT; i++) {
        const dur = VOL_DURATIONS[i % VOL_DURATIONS.length];
        $volVis.append(`<div class="cr-vol-bar" style="animation-duration: ${dur}s; animation-delay: -${(i * 0.09 % dur).toFixed(2)}s"></div>`);
    }
    const volBars = $volVis.children('.cr-vol-bar');

    function updateVolAnimState() {
        const playing = isPlaying && !isLoading && !audioObj.paused && audioObj.volume > 0;
        const real = playing && spectrumRealActive;
        $volVis.toggleClass('playing', playing);
        $volVis.toggleClass('real-spectrum', real);
        if (real) startSpectrumLoop(); else stopSpectrumLoop();
    }

    // === 真实音频频谱引擎状态（声明须先于初始化期的首次 updateVolumeUI 调用，函数体在后方原 rAF 循环位置） ===
    let spectrumCtx = null, spectrumAnalyser = null, spectrumSource = null;
    let spectrumRafId = 0, spectrumZeroFrames = 0, spectrumData = null;
    let spectrumRealActive = false, spectrumFallbackToasted = false;
    const spectrumCorsCache = {};
    const SPECTRUM_BIN_IDX = [];
    for (let i = 0; i < VOL_BAR_COUNT; i++) SPECTRUM_BIN_IDX.push(1 + Math.round(Math.pow(i / (VOL_BAR_COUNT - 1), 1.6) * 79));

    function updateVolumeUI(vol) {
        let pct = Math.round(vol * 100);
        $('#cr-vol-slider').val(pct);
        $('#cr-vol-text').text(pct + '%');
        $volVis[0].style.setProperty('--cr-vol', vol);
        updateVolAnimState();

        const activeCount = Math.round(vol * VOL_BAR_COUNT);
        volBars.each(function(idx) {
            if (idx < activeCount) {
                $(this).addClass('active');
            } else {
                $(this).removeClass('active');
            }
        });

        const svgSpeakerHigh = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#C4A77D" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="rgba(196,167,125,0.2)"></polygon><path d="M15.5 8.5a5 5 0 0 1 0 7"></path><path d="M19 5a10 10 0 0 1 0 14"></path></svg>`;
        const svgSpeakerLow = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#C4A77D" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="rgba(196,167,125,0.2)"></polygon><path d="M15.5 8.5a5 5 0 0 1 0 7"></path></svg>`;
        const svgSpeakerMute = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#D34B4B" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="rgba(211,75,75,0.2)"></polygon><line x1="22" y1="9" x2="16" y2="15"></line><line x1="16" y1="9" x2="22" y2="15"></line></svg>`;

        if (vol === 0) {
            $('#cr-vol-icon').html(svgSpeakerMute).attr('title', '已静音 (点击恢复)');
        } else if (vol < 0.5) {
            $('#cr-vol-icon').html(svgSpeakerLow).attr('title', '音量较小 (点击静音)');
