                        <input type="text" class="cp-input cr-new-song-input" id="new-song-input-${cIdx}" placeholder="歌名 - 歌手(或填网址)" autocomplete="off" style="font-size:10px; padding:3px 6px;">
                        <button class="cp-btn cr-add-song" data-idx="${cIdx}" style="color:#C4A77D; border-color:rgba(196,167,125,0.3); padding:3px 7px; font-size:10px;">刻录</button>
                    </div>`;

            if (isBatchMode) {
                let isAllSel = cat.songs.length > 0 && selectedSongsSet.size === cat.songs.length;
                html += `<div class="cr-batch-bar" style="display:flex; align-items:center; justify-content:space-between; padding:5px 8px; margin:4px 6px 8px; background:rgba(196,167,125,0.08); border:1px solid rgba(196,167,125,0.25); border-radius:4px; font-size:10px;">
                    <div style="display:flex; align-items:center; gap:6px;">
                        <input type="checkbox" class="cr-batch-select-all" data-pidx="${cIdx}" ${isAllSel ? 'checked' : ''} style="cursor:pointer; accent-color:#C4A77D;" title="全选 / 取消全选">
                        <span style="color:#C4A77D; font-weight:600;">已选 ${selectedSongsSet.size}/${cat.songs.length}</span>
                    </div>
                    <div style="display:flex; align-items:center; gap:4px;">
                        <button class="cr-batch-fav-btn" data-pidx="${cIdx}" style="background:rgba(255,255,255,0.06); border:1px solid rgba(196,167,125,0.4); color:#C4A77D; padding:2px 6px; border-radius:3px; font-size:9px; cursor:pointer;" title="批量收藏到【★ 我的收藏】">★ 收藏</button>
                        <button class="cr-batch-move-btn" data-pidx="${cIdx}" style="background:rgba(255,255,255,0.06); border:1px solid rgba(196,167,125,0.4); color:#C4A77D; padding:2px 6px; border-radius:3px; font-size:9px; cursor:pointer;" title="批量迁移到其他频段">⇄ 迁移</button>
                        <button class="cr-batch-del-btn" data-pidx="${cIdx}" style="background:rgba(255,50,50,0.1); border:1px solid rgba(255,80,80,0.4); color:#ff7875; padding:2px 6px; border-radius:3px; font-size:9px; cursor:pointer;" title="批量删除选中曲目">🗑️ 删除</button>
                        <button class="cr-batch-exit-btn" data-pidx="${cIdx}" style="background:none; border:none; color:#888; padding:2px 4px; font-size:11px; cursor:pointer;" title="退出多选">✕</button>
