                <button class="cp-btn cr-online-search-btn" style="margin-top: 12px; padding: 4px 10px; border-color: #C4A77D; color: #C4A77D;" data-query="${globalSearchQuery}">🌐 全网检索并试听</button>
            </div>`;
        }

        $('#bgm-playlists').html(html);
        updatePlayerFavBtn();
