                $('#bgm-now-artist').text(song.artist || 'Unknown Node');
                localStorage.setItem('cr_last_song_title', song.title);
                localStorage.setItem('cr_last_song_artist', song.artist || '');
                recordPlayHistory(song.title, song.artist);
