            isPlaying = false;
            $('.song-item').removeClass('loading');
            $('#bgm-now-playing').text(`[连接丢失]`);
            $('#bgm-now-artist').text(song.title);
            updateBgmUI();
            showPlayerToast("⚠️ 该信标失效，2秒后跳跃至下一首...", 2000);
