    function getAllLibrarySongs() {
        let all = [];
        bgmPlaylists.forEach((pl, pIdx) => {
            pl.songs.forEach((song, sIdx) => {
                all.push({ pIdx, sIdx, song });
            });
        });
        return all;
    }

    function prevSong() {
        let allSongs = getAllLibrarySongs();
        if (allSongs.length === 0) return;

        if (playMode === 'shuffle_all') {
            let candidatePool = allSongs;
            if (allSongs.length > 1 && currentPlaylistIndex !== -1) {
                candidatePool = allSongs.filter(item => !(item.pIdx === currentPlaylistIndex && item.sIdx === currentSongIndex));
            }
            let pick = candidatePool[Math.floor(Math.random() * candidatePool.length)];
            playSpecificSong(pick.pIdx, pick.sIdx);
            return;
        }

        if (currentPlaylistIndex === -1) {
            let validLists = bgmPlaylists.map((pl, idx) => ({pl, idx})).filter(item => item.pl.songs.length > 0);
            if (validLists.length === 0) return;
            let targetList = validLists[0];
            playSpecificSong(targetList.idx, 0);
            return;
        }

        let list = bgmPlaylists[currentPlaylistIndex].songs;
        if (!list || list.length === 0) return;

        let targetIdx = currentSongIndex;
        if (playMode === 'list_random') {
            if (list.length > 1) {
                let pool = [];
                for (let i = 0; i < list.length; i++) {
                    if (i !== currentSongIndex) pool.push(i);
                }
                targetIdx = pool[Math.floor(Math.random() * pool.length)];
            } else {
                targetIdx = 0;
            }
        } else {
            targetIdx = (currentSongIndex <= 0) ? list.length - 1 : currentSongIndex - 1;
        }
        playSpecificSong(currentPlaylistIndex, targetIdx);
    }

    function nextSong() {
        let allSongs = getAllLibrarySongs();
        if (allSongs.length === 0) return;

        if (playMode === 'shuffle_all') {
            let candidatePool = allSongs;
            if (allSongs.length > 1 && currentPlaylistIndex !== -1) {
                candidatePool = allSongs.filter(item => !(item.pIdx === currentPlaylistIndex && item.sIdx === currentSongIndex));
            }
            let pick = candidatePool[Math.floor(Math.random() * candidatePool.length)];
            playSpecificSong(pick.pIdx, pick.sIdx);
            return;
        }

        if (currentPlaylistIndex === -1) {
            let validLists = bgmPlaylists.map((pl, idx) => ({pl, idx})).filter(item => item.pl.songs.length > 0);
            if (validLists.length === 0) return;
            let targetList = validLists[0];
            playSpecificSong(targetList.idx, 0);
            return;
        }

        let list = bgmPlaylists[currentPlaylistIndex].songs;
        if (!list || list.length === 0) return;

        let targetIdx = currentSongIndex;
        if (playMode === 'list_random') {
            if (list.length > 1) {
                let pool = [];
                for (let i = 0; i < list.length; i++) {
                    if (i !== currentSongIndex) pool.push(i);
                }
                targetIdx = pool[Math.floor(Math.random() * pool.length)];
            } else {
                targetIdx = 0;
            }
        } else {
            targetIdx = (currentSongIndex >= list.length - 1) ? 0 : currentSongIndex + 1;
        }
        playSpecificSong(currentPlaylistIndex, targetIdx);
    }

    let lastHandledMessageId = null;

    // === 双擎雷达 1：SillyTavern 原生事件拦截 (自动触发 AI DJ 或文本指令) ===
    let stScanTimer = null;
    const onMessageChange = (messageId) => {
        if (stScanTimer) clearTimeout(stScanTimer);
        stScanTimer = setTimeout(() => {
            try {
                const djCfg = getDjSettings();

                // 优先检查正文中是否直接嵌入了 [点一首歌: ...]
                let textContent = "";
                if (typeof getChatMessages === 'function') {
                    const msgs = getChatMessages(messageId);
                    if (msgs && msgs.length > 0) {
                        const msg = msgs[0];
                        if (msg.role === 'assistant' || msg.is_user === false) {
                            textContent = msg.message || msg.mes || "";
                        }
                    }
        } else if (typeof window.parent.getChatMessages === 'function') {
                    const msgs = window.parent.getChatMessages(messageId);
                    if (msgs && msgs.length > 0) {
                        const msg = msgs[0];
                        if (msg.role === 'assistant' || msg.is_user === false) {
                            textContent = msg.message || msg.mes || "";
                        }
                    }
        }

                const regex = /\[\s*点一首歌\s*[:：]\s*([^\]]+?)\s*\]/g;
                let match = regex.exec(textContent);
                if (match) {
                    let rawContent = (match[1] || "").trim();
                    let songTitle = rawContent;
                    let songArtist = "";
                    let splitIdx = rawContent.lastIndexOf('-');
                    if (splitIdx !== -1) {
                        songTitle = rawContent.substring(0, splitIdx).trim();
                        songArtist = rawContent.substring(splitIdx + 1).trim();
                    }
                    playDirect(songTitle, songArtist);
            return;
        }

                // 若正文未嵌入选歌指令，且开启了 AI DJ 自动选歌与配置了 API Key
                if (djCfg.autoTrigger && djCfg.apiKey && messageId !== lastHandledMessageId) {
                    lastHandledMessageId = messageId;
                    triggerAiDjDecision(false);
        }
            } catch(e) {}
        }, 1500);
    };

    try {
        if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
            eventOn(tavern_events.MESSAGE_SWIPED, onMessageChange);
            eventOn(tavern_events.MESSAGE_UPDATED, onMessageChange);
            eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, onMessageChange);
            eventOn(tavern_events.MESSAGE_RECEIVED, onMessageChange);
            console.log("太空电台：已成功接入 SillyTavern 原生事件雷达与 Sidecar AI DJ 引擎！");
        } else if (typeof window.parent.eventOn === 'function' && typeof window.parent.tavern_events !== 'undefined') {
            window.parent.eventOn(window.parent.tavern_events.MESSAGE_SWIPED, onMessageChange);
            window.parent.eventOn(window.parent.tavern_events.MESSAGE_UPDATED, onMessageChange);
            window.parent.eventOn(window.parent.tavern_events.CHARACTER_MESSAGE_RENDERED, onMessageChange);
            window.parent.eventOn(window.parent.tavern_events.MESSAGE_RECEIVED, onMessageChange);
            console.log("太空电台：已成功接入宿主 SillyTavern 原生事件雷达！");
        }
    } catch(e) {}

    // === 启动初始化记忆恢复与播放控制 ===
    setTimeout(() => {
        let initAutoplay = localStorage.getItem('cr_init_autoplay') === 'true';
        let lastTitle = localStorage.getItem('cr_last_song_title');
        let lastArtist = localStorage.getItem('cr_last_song_artist');

        if (initAutoplay) {
            if (lastTitle) {
                playDirect(lastTitle, lastArtist || '');
            } else {
                playDirect('Echoes of the Eye', '');
            }
        } else {
            // 静默待机模式：回填曲目信息但暂不自动播放音频
            if (lastTitle) {
                let loc = findSongInPlaylists(lastTitle, lastArtist);
                if (loc) {
                    currentPlaylistIndex = loc.pIdx;
                    currentSongIndex = loc.sIdx;
                }
                currentPlayingTrackInfo = { title: lastTitle, artist: lastArtist || '未知艺术家', url: '' };
                $('#bgm-current-title').text(lastTitle);
                $('#bgm-current-artist').text(lastArtist ? `- ${lastArtist}` : '');
                $('#bgm-current-cat').text(currentPlaylistIndex >= 0 ? `[${bgmPlaylists[currentPlaylistIndex].category}]` : '[记忆曲目]');
                updatePlayerFavBtn();
            } else {
                $('#bgm-current-title').text('天式号·太空电台');
                $('#bgm-current-artist').text('就绪 (待机中)');
                $('#bgm-current-cat').text('[待机]');
            }
            isPlaying = false;
            updateBgmUI();
        }
    }, 1000);

    // 页面卸载时安全销毁
    $(window).on('pagehide', () => {
        $('#celestial-radio-container, #celestial-radio-css, #celestial-drag-overlay, #cr-move-modal, #cr-settings-modal').remove();
    });

})();
